```c
// hist.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "hist.h"

#define BUCKET_COUNT 10

static void compute_histogram(const double* data, size_t n, int* buckets) {
    memset(buckets, 0, BUCKET_COUNT * sizeof(int));
    if (n == 0) return;

    double min = data[0], max = data[0];
    for (size_t i = 1; i < n; i++) {
        if (data[i] < min) min = data[i];
        if (data[i] > max) max = data[i];
    }

    double range = max - min;
    if (range == 0) range = 1.0;

    for (size_t i = 0; i < n; i++) {
        int bucket = (int)((data[i] - min) / range * (BUCKET_COUNT - 1));
        if (bucket >= BUCKET_COUNT) bucket = BUCKET_COUNT - 1;
        buckets[bucket]++;
    }
}

int histogram_batch(const double* data, size_t n, char** out_json) {
    if (!data || !out_json) return -1;

    int buckets[BUCKET_COUNT];
    compute_histogram(data, n, buckets);

    size_t json_size = 256 + BUCKET_COUNT * 64;
    char* json = (char*)malloc(json_size);
    if (!json) return -1;

    snprintf(json, json_size, "{\"count\":%zu,\"buckets\":[", n);
    size_t pos = strlen(json);

    for (int i = 0; i < BUCKET_COUNT; i++) {
        int written = snprintf(json + pos, json_size - pos, 
            "%s%d", (i > 0 ? "," : ""), buckets[i]);
        pos += written;
    }

    snprintf(json + pos, json_size - pos, "]}");
    *out_json = json;
    return 0;
}
```

```go
// hist.go
package main

/*
#cgo CFLAGS: -O2
#cgo LDFLAGS: -L. -lhist
#include "hist.h"
#include <stdlib.h>

static inline int go_histogram_batch(const double* data, size_t n, char** out_json) {
    return histogram_batch(data, n, out_json);
}
*/
import "C"
import (
	"fmt"
	"runtime"
	"unsafe"
)

func ComputeHistogramBatch(nums []float64) (string, error) {
	if len(nums) == 0 {
		return "", fmt.Errorf("empty input slice")
	}

	var jsonPtr *C.char
	n := C.size_t(len(nums))

	cNums := (*C.double)(unsafe.Pointer(&nums[0]))

	result := C.go_histogram_batch(cNums, n, &jsonPtr)
	if result != 0 {
		return "", fmt.Errorf("histogram_batch failed with code %d", result)
	}

	jsonStr := C.GoString(jsonPtr)
	C.free(unsafe.Pointer(jsonPtr))

	runtime.KeepAlive(nums)

	return jsonStr, nil
}
```

```go
// main.go
package main

import (
	"fmt"
	"sync"
)

type Job struct {
	ID  int
	Num []float64
}

type Result struct {
	JobID    int
	JSON     string
	Err      error
}

func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
	defer wg.Done()
	for job := range jobs {
		json, err := ComputeHistogramBatch(job.Num)
		results <- Result{
			JobID: job.ID,
			JSON: json,
			Err:  err,
		}
	}
}

func main() {
	numWorkers := 4
	numJobs := 100

	jobs := make(chan Job, numJobs)
	results := make(chan Result, numJobs)

	var wg sync.WaitGroup

	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go worker(jobs, results, &wg)
	}

	for i := 0; i < numJobs; i++ {
		nums := make([]float64, 1000)
		for j := range nums {
			nums[j] = float64(j % 100)
		}
		jobs <- Job{ID: i, Num: nums}
	}
	close(jobs)

	go func() {
		wg.Wait()
		close(results)
	}()

	for result := range results {
		if result.Err != nil {
			fmt.Printf("Job %d error: %v\n", result.JobID, result.Err)
		} else {
			fmt.Printf("Job %d: %s\n", result.JobID, result.JSON)
		}
	}
}
```

## Key Takeaways

1. **Memory Safety**: The Go binding calls `C.free()` on the pointer returned by C to prevent memory leaks
2. **Concurrency**: Each call operates on independent data with no shared mutable state, making it inherently thread-safe
3. **Zero-Copy Slicing**: `unsafe.Pointer` allows passing Go slice data to C without copying, but `runtime.KeepAlive` ensures the slice isn't garbage collected during the C call
4. **Error Handling**: Return values propagate errors from C to Go via integer status codes

