```c
// render_flags.c
#include "render_flags.h"
#include <string.h>
#include <stddef.h>
void render_flags_json(const int* flags, size_t n, char* out, size_t max_len, int* err) {
  if (max_len == 0 || !out) { if (err) *err = 1; return; }
  size_t pos = 0;
  if (out) out[0] = '['; pos = 1;
  for (size_t i = 0; i < n; ++i) {
    const char* s = flags[i] ? "true" : "false";
    size_t len = strlen(s);
    if (pos + len + (i+1 < n ? 1 : 0) + 1 > max_len) { if (err) *err = 1; if (out) out[0] = '\0'; return; }
    if (out) memcpy(out + pos, s, len);
    pos += len;
    if (i + 1 < n) { if (out) out[pos] = ','; pos++; }
  }
  if (out) out[pos] = ']'; pos++;
  if (out) out[pos] = '\0';
  if (err) *err = 0;
}
```
```go
// render_flags.go
package main
/*
#include "render_flags.h"
#include <stdlib.h>
*/
import "C"
import (
  "errors"
)
func RenderFlagsJSON(flags []bool) (string, error) {
  n := len(flags)
  cflags := make([]C.int, n)
  for i, b := range flags { if b { cflags[i] = 1 } else { cflags[i] = 0 } }
  maxLen := C.size_t(256)
  buf := C.malloc(maxLen)
  if buf == nil { return "", errors.New("allocation failed") }
  defer C.free(buf)
  var ferr C.int
  C.render_flags_json((*C.int)(&cflags[0]), C.size_t(n), (*C.char)(buf), maxLen, &ferr)
  if ferr != 0 { return "", errors.New("render failed") }
  return C.GoString((*C.char)(buf)), nil
}
